-- Owner-approved public school pages with independent draft and published snapshots.
CREATE TABLE website_pages (
 school_id uuid NOT NULL REFERENCES schools(id), slug text NOT NULL,
 draft_content jsonb NOT NULL CHECK(jsonb_typeof(draft_content)='object'),
 published_content jsonb CHECK(published_content IS NULL OR jsonb_typeof(published_content)='object'),
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0), published_revision integer,
 published_at timestamptz, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(school_id,slug), FOREIGN KEY(school_id,updated_by) REFERENCES user_accounts(school_id,id)
);
CREATE TABLE website_assets (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES schools(id),
 filename text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image/webp','application/pdf')),
 file_bytes bytea NOT NULL CHECK(octet_length(file_bytes) BETWEEN 20 AND 5242880),
 alt_text text NOT NULL DEFAULT '',caption text NOT NULL DEFAULT '',checksum_sha256 char(64) NOT NULL,
 publication_authorized_at timestamptz NOT NULL DEFAULT now(),uploaded_by uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,id),
 FOREIGN KEY(school_id,uploaded_by) REFERENCES user_accounts(school_id,id)
);
CREATE TABLE website_page_history (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,slug text NOT NULL,
 action text NOT NULL CHECK(action IN ('OWNER_APPROVED_INITIAL','SAVE_DRAFT','PUBLISH','WITHDRAW')),
 revision integer NOT NULL,snapshot jsonb,actor_user_id uuid,note text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(school_id,slug) REFERENCES website_pages(school_id,slug),
 FOREIGN KEY(school_id,actor_user_id) REFERENCES user_accounts(school_id,id)
);
CREATE INDEX website_page_history_order ON website_page_history(school_id,slug,created_at DESC,id DESC);
GRANT SELECT,INSERT,UPDATE ON website_pages TO redeemer_runtime;
GRANT SELECT,INSERT ON website_assets,website_page_history TO redeemer_runtime;
ALTER TABLE website_pages ENABLE ROW LEVEL SECURITY;
ALTER TABLE website_pages FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_school_scope ON website_pages USING(school_id=app.current_school_id()) WITH CHECK(school_id=app.current_school_id());
ALTER TABLE website_assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE website_assets FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_school_scope ON website_assets USING(school_id=app.current_school_id()) WITH CHECK(school_id=app.current_school_id());
ALTER TABLE website_page_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE website_page_history FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_school_scope ON website_page_history USING(school_id=app.current_school_id()) WITH CHECK(school_id=app.current_school_id());
INSERT INTO website_pages(school_id,slug,draft_content,published_content,revision,published_revision,published_at) SELECT id,'home','{"eyebrow": "Home", "heading": "Growing minds. Building character. Inspiring tomorrow.", "intro": "Discover Redeemer’s International Academy, a learning community rooted in academic and moral excellence in Thinker’s Village, Paynesville.", "sections": [], "images": [], "documents": [], "profile": {"name": "Redeemer''s International Academy", "motto": "Academic and Moral Excellence", "founded": "2022", "address": "RIA Highway, Thinker''s Village, Guest House Road, Paynesville, Montserrado, Liberia", "phones": ["0778786116", "0555664239"]}, "blocks": {"about": {"title": "A community where every learner matters", "body": "Welcome to Redeemer''s International Academy in Paynesville, Liberia. Our motto, “Academic and Moral Excellence,” expresses the standard we aim to uphold in learning, conduct and school life.\n\nThis website helps families explore the school, ask questions, request a visit and begin an admission application. The school office can explain current admission requirements and the next steps for your family."}, "academics": {"title": "Learning beyond the classroom", "body": "Our approach combines classroom teaching, consistent assessment, family participation and opportunities for students to develop personal responsibility. For grade availability, curriculum details, and enrollment requirements, contact the school office."}, "admissions": {"title": "Begin your child''s journey", "body": "Interested families can start an official application online. The school’s admissions team will review submitted information and communicate the next steps."}, "families": {"title": "Student & family resources", "body": "Students and guardians can use their secure accounts to view school notices, learning resources, attendance, grades and authorized tuition information."}}}'::jsonb,'{"eyebrow": "Home", "heading": "Growing minds. Building character. Inspiring tomorrow.", "intro": "Discover Redeemer’s International Academy, a learning community rooted in academic and moral excellence in Thinker’s Village, Paynesville.", "sections": [], "images": [], "documents": [], "profile": {"name": "Redeemer''s International Academy", "motto": "Academic and Moral Excellence", "founded": "2022", "address": "RIA Highway, Thinker''s Village, Guest House Road, Paynesville, Montserrado, Liberia", "phones": ["0778786116", "0555664239"]}, "blocks": {"about": {"title": "A community where every learner matters", "body": "Welcome to Redeemer''s International Academy in Paynesville, Liberia. Our motto, “Academic and Moral Excellence,” expresses the standard we aim to uphold in learning, conduct and school life.\n\nThis website helps families explore the school, ask questions, request a visit and begin an admission application. The school office can explain current admission requirements and the next steps for your family."}, "academics": {"title": "Learning beyond the classroom", "body": "Our approach combines classroom teaching, consistent assessment, family participation and opportunities for students to develop personal responsibility. For grade availability, curriculum details, and enrollment requirements, contact the school office."}, "admissions": {"title": "Begin your child''s journey", "body": "Interested families can start an official application online. The school’s admissions team will review submitted information and communicate the next steps."}, "families": {"title": "Student & family resources", "body": "Students and guardians can use their secure accounts to view school notices, learning resources, attendance, grades and authorized tuition information."}}}'::jsonb,1,1,now() FROM schools WHERE code='RIA';
