INSERT INTO website_pages(school_id,slug,draft_content,published_content,revision,published_revision,published_at) SELECT id,'mission-values','{"eyebrow": "School Info", "heading": "Our Mission & Values", "intro": "Academic and Moral Excellence is the guiding motto of Redeemerâ€™s International Academy.", "sections": [{"title": "Our mission", "body": "Our mission is to help learners grow in knowledge, character and responsibility through purposeful learning and cooperation between school and home."}, {"title": "Our values", "body": "Learning: ask questions, practise skills and keep improving.\nIntegrity: speak honestly and take responsibility for actions.\nRespect: treat people and shared spaces with care.\nService: contribute positively to the school and wider community.\nPartnership: work together as learners, families and staff."}], "images": [], "documents": []}'::jsonb,'{"eyebrow": "School Info", "heading": "Our Mission & Values", "intro": "Academic and Moral Excellence is the guiding motto of Redeemerâ€™s International Academy.", "sections": [{"title": "Our mission", "body": "Our mission is to help learners grow in knowledge, character and responsibility through purposeful learning and cooperation between school and home."}, {"title": "Our values", "body": "Learning: ask questions, practise skills and keep improving.\nIntegrity: speak honestly and take responsibility for actions.\nRespect: treat people and shared spaces with care.\nService: contribute positively to the school and wider community.\nPartnership: work together as learners, families and staff."}], "images": [], "documents": []}'::jsonb,1,1,now() FROM schools WHERE code='RIA';
