INSERT INTO website_pages(school_id,slug,draft_content,published_content,revision,published_revision,published_at) SELECT id,'principal-message','{"eyebrow": "School Info", "heading": "A Message from the Principal", "intro": "Welcome to Redeemerâ€™s International Academy.", "sections": [{"title": "Welcome from the Principal", "body": "Welcome to Redeemer''s International Academy.\n\nChoosing a school is an important decision for every family. We want our website to give you a clear introduction to our school and a practical way to contact us, arrange a visit or begin an application.\n\n“Academic and Moral Excellence” asks us to value both what learners achieve and how they learn, treat others and contribute to their community. We look forward to working with families as partners in that journey.\n\nPlease contact the school office with your questions. We welcome the opportunity to explain our programmes and help you understand the next steps.\n\nPrincipal, Redeemer''s International Academy"}], "images": [], "documents": []}'::jsonb,'{"eyebrow": "School Info", "heading": "A Message from the Principal", "intro": "Welcome to Redeemerâ€™s International Academy.", "sections": [{"title": "Welcome from the Principal", "body": "Welcome to Redeemer''s International Academy.\n\nChoosing a school is an important decision for every family. We want our website to give you a clear introduction to our school and a practical way to contact us, arrange a visit or begin an application.\n\n“Academic and Moral Excellence” asks us to value both what learners achieve and how they learn, treat others and contribute to their community. We look forward to working with families as partners in that journey.\n\nPlease contact the school office with your questions. We welcome the opportunity to explain our programmes and help you understand the next steps.\n\nPrincipal, Redeemer''s International Academy"}], "images": [], "documents": []}'::jsonb,1,1,now() FROM schools WHERE code='RIA';
