INSERT INTO website_pages(school_id,slug,draft_content,published_content,revision,published_revision,published_at) SELECT id,'parent-handbook','{"eyebrow": "Parents", "heading": "Parent Handbook", "intro": "Information for families about the topics covered by the school handbook.", "sections": [{"title": "Handbook contents", "body": "1. Welcome, purpose, version date and approval authority.\n2. School contacts, hours and calendar.\n3. Arrival, attendance, late arrival, absence and collection arrangements.\n4. Learning, homework, assessment and reporting.\n5. Conduct, behaviour review and school-family concerns process.\n6. Learner wellbeing, safeguarding and the school''s named reporting contact.\n7. Health, illness, medication, allergies and emergency arrangements.\n8. Uniform, supplies, meals and transport/services actually offered.\n9. Fees, approved payment channels and financial queries.\n10. Privacy, photographs, school records and portal use.\n11. Visits, events and communication expectations.\n12. Acknowledgment and review date."}, {"title": "School guidance", "body": "Contact the school office for the current detailed policies and guidance. The administration will keep this page and its approved documents up to date."}], "images": [], "documents": []}'::jsonb,'{"eyebrow": "Parents", "heading": "Parent Handbook", "intro": "Information for families about the topics covered by the school handbook.", "sections": [{"title": "Handbook contents", "body": "1. Welcome, purpose, version date and approval authority.\n2. School contacts, hours and calendar.\n3. Arrival, attendance, late arrival, absence and collection arrangements.\n4. Learning, homework, assessment and reporting.\n5. Conduct, behaviour review and school-family concerns process.\n6. Learner wellbeing, safeguarding and the school''s named reporting contact.\n7. Health, illness, medication, allergies and emergency arrangements.\n8. Uniform, supplies, meals and transport/services actually offered.\n9. Fees, approved payment channels and financial queries.\n10. Privacy, photographs, school records and portal use.\n11. Visits, events and communication expectations.\n12. Acknowledgment and review date."}, {"title": "School guidance", "body": "Contact the school office for the current detailed policies and guidance. The administration will keep this page and its approved documents up to date."}], "images": [], "documents": []}'::jsonb,1,1,now() FROM schools WHERE code='RIA';
